import type { Attribute, Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  sidebarClassName,
  sidebarContentClassName,
  sidebarFooterClassName,
  sidebarGroupClassName,
  sidebarGroupLabelClassName,
  sidebarHeaderClassName,
  sidebarIconClassName,
  sidebarInsetClassName,
  sidebarLabelClassName,
  sidebarMenuButtonClassName,
  sidebarMenuClassName,
  sidebarMenuItemClassName,
  sidebarProviderClassName,
  sidebarRailClassName,
} from "./view";

export {
  sidebarClassName,
  sidebarContentClassName,
  sidebarFooterClassName,
  sidebarGroupClassName,
  sidebarGroupLabelClassName,
  sidebarHeaderClassName,
  sidebarIconClassName,
  sidebarInsetClassName,
  sidebarLabelClassName,
  sidebarMenuButtonClassName,
  sidebarMenuClassName,
  sidebarMenuItemClassName,
  sidebarProviderClassName,
  sidebarRailClassName,
} from "./view";

export type SidebarState = "expanded" | "collapsed";

export type SidebarMenuItem<ParentMessage> = Readonly<{
  label: string;
  icon: string;
  active?: boolean;
  href?: string;
  onClick?: ParentMessage;
}>;

type ViewConfig<ParentMessage> = Readonly<{
  children: readonly (Html | string)[];
  className?: string;
  attributes?: readonly Attribute<ParentMessage>[];
}>;

export type SidebarViewConfig<ParentMessage> = ViewConfig<ParentMessage> &
  Readonly<{
    state?: SidebarState;
  }>;

export type SidebarMenuButtonViewConfig<ParentMessage> = Readonly<{
  item: SidebarMenuItem<ParentMessage>;
  state?: SidebarState;
  className?: string;
}>;

const classNames = (...values: readonly (string | undefined)[]): string =>
  values
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const providerView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "sidebar-provider"),
      h.Class(classNames(sidebarProviderClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const sidebarView = <ParentMessage>({
  children,
  state = "expanded",
  className,
  attributes = [],
}: SidebarViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.aside(
    [
      h.DataAttribute("slot", "sidebar"),
      h.DataAttribute("state", state),
      h.AriaLabel("Application sidebar"),
      h.Class(classNames(sidebarClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const headerView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "sidebar-header"),
      h.Class(classNames(sidebarHeaderClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const contentView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "sidebar-content"),
      h.Class(classNames(sidebarContentClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const footerView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "sidebar-footer"),
      h.Class(classNames(sidebarFooterClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const groupView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "sidebar-group"),
      h.Class(classNames(sidebarGroupClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const groupLabelView = <ParentMessage>(
  label: string,
  state: SidebarState = "expanded"
): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "sidebar-group-label"),
      h.DataAttribute("state", state),
      h.Class(sidebarGroupLabelClassName),
    ],
    [label]
  );
};

export const menuView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.ul(
    [
      h.DataAttribute("slot", "sidebar-menu"),
      h.Class(classNames(sidebarMenuClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const menuItemView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.li(
    [
      h.DataAttribute("slot", "sidebar-menu-item"),
      h.Class(classNames(sidebarMenuItemClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const menuButtonView = <ParentMessage>({
  item,
  state = "expanded",
  className,
}: SidebarMenuButtonViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();
  const attributes = [
    h.DataAttribute("slot", "sidebar-menu-button"),
    h.DataAttribute("active", item.active === true ? "true" : "false"),
    h.AriaCurrent(item.active === true ? "page" : "false"),
    h.AriaLabel(item.label),
    h.Class(classNames(sidebarMenuButtonClassName, className)),
    ...(item.onClick === undefined ? [] : [h.OnClick(item.onClick)]),
  ];
  const children = [
    h.span(
      [
        h.DataAttribute("slot", "sidebar-menu-icon"),
        h.Class(sidebarIconClassName),
      ],
      [item.icon]
    ),
    h.span(
      [
        h.DataAttribute("slot", "sidebar-menu-label"),
        h.DataAttribute("state", state),
        h.Class(sidebarLabelClassName),
      ],
      [item.label]
    ),
  ];

  return item.href === undefined
    ? h.button(attributes, children)
    : h.a([h.Href(item.href), ...attributes], children);
};

export const railView = <ParentMessage>(): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.AriaHidden(true),
      h.DataAttribute("slot", "sidebar-rail"),
      h.Class(sidebarRailClassName),
    ],
    []
  );
};

export const insetView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.main(
    [
      h.DataAttribute("slot", "sidebar-inset"),
      h.Class(classNames(sidebarInsetClassName, className)),
      ...attributes,
    ],
    children
  );
};

const hBrand = <ParentMessage>(
  icon: string,
  label: string,
  state: SidebarState
): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [h.Class("flex min-w-0 items-center gap-3")],
    [
      h.span([h.Class(sidebarIconClassName)], [icon]),
      h.span(
        [
          h.DataAttribute("slot", "sidebar-brand-label"),
          h.DataAttribute("state", state),
          h.Class(
            "truncate text-sm font-semibold text-gray-950 data-[state=collapsed]:sr-only"
          ),
        ],
        [label]
      ),
    ]
  );
};

export const view = <ParentMessage>({
  state = "expanded",
  items,
  children,
}: Readonly<{
  state?: SidebarState;
  items: readonly SidebarMenuItem<ParentMessage>[];
  children: readonly (Html | string)[];
}>): Html =>
  providerView<ParentMessage>({
    children: [
      sidebarView<ParentMessage>({
        state,
        children: [
          headerView<ParentMessage>({
            children: [hBrand<ParentMessage>("AC", "Acme Inc.", state)],
          }),
          contentView<ParentMessage>({
            children: [
              groupView<ParentMessage>({
                children: [
                  groupLabelView<ParentMessage>("Platform", state),
                  menuView<ParentMessage>({
                    children: items.map((item) =>
                      menuItemView<ParentMessage>({
                        children: [
                          menuButtonView<ParentMessage>({ item, state }),
                        ],
                      })
                    ),
                  }),
                ],
              }),
            ],
          }),
          footerView<ParentMessage>({
            children: [state === "expanded" ? "Team workspace" : "Team"],
          }),
        ],
      }),
      railView<ParentMessage>(),
      insetView<ParentMessage>({ children }),
    ],
  });

export const sidebarProviderClassName =
  "flex min-h-80 w-full overflow-hidden rounded-lg border border-gray-200 bg-white text-gray-950";

export const sidebarClassName =
  "flex shrink-0 flex-col border-gray-200 bg-gray-50 transition-[width] duration-200 data-[state=collapsed]:w-16 data-[state=expanded]:w-64";

export const sidebarHeaderClassName =
  "flex min-h-14 items-center gap-3 border-b border-gray-200 px-3";

export const sidebarContentClassName = "flex-1 space-y-4 overflow-auto p-3";

export const sidebarFooterClassName =
  "border-t border-gray-200 p-3 text-xs text-gray-500";

export const sidebarGroupClassName = "space-y-2";

export const sidebarGroupLabelClassName =
  "px-2 text-xs font-medium text-gray-500 data-[state=collapsed]:sr-only";

export const sidebarMenuClassName = "space-y-1";

export const sidebarMenuItemClassName = "list-none";

export const sidebarMenuButtonClassName =
  "flex h-9 w-full items-center gap-3 rounded-md px-2 text-left text-sm font-medium text-gray-700 transition hover:bg-gray-100 hover:text-gray-950 focus:outline-none focus-visible:ring-2 focus-visible:ring-accent-500 data-[active=true]:bg-white data-[active=true]:text-gray-950 data-[active=true]:shadow-sm";

export const sidebarIconClassName =
  "flex size-6 shrink-0 items-center justify-center rounded-md bg-white text-xs font-semibold text-gray-600 shadow-sm";

export const sidebarLabelClassName =
  "min-w-0 truncate data-[state=collapsed]:sr-only";

export const sidebarInsetClassName =
  "min-w-0 flex-1 overflow-auto bg-white p-6";

export const sidebarRailClassName =
  "w-2 shrink-0 border-l border-gray-200 bg-gray-100";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Sidebar from "./index";

type Message = Readonly<{ readonly _tag: "ClickedDashboard" }>;

const view = (): Html => {
  const h = html<Message>();

  return Sidebar.view<Message>({
    state: "collapsed",
    items: [
      {
        label: "Dashboard",
        icon: "D",
        active: true,
        onClick: { _tag: "ClickedDashboard" },
      },
      { label: "Settings", icon: "S", href: "/settings" },
    ],
    children: [
      h.h2([h.Class("text-lg font-semibold text-gray-950")], ["Dashboard"]),
    ],
  });
};

describe("Sidebar registry view", () => {
  test("renders the shadcn sidebar anatomy and controlled collapsed state", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Acme Inc.")).toHaveAttr(
        "data-state",
        "collapsed"
      ),
      Scene.expect(Scene.text("Dashboard")).toHaveAttr(
        "data-slot",
        "sidebar-menu-label"
      ),
      Scene.expect(Scene.role("button", { name: "Dashboard" })).toHaveAttr(
        "data-active",
        "true"
      ),
      Scene.expect(Scene.role("button", { name: "Dashboard" })).toHaveAttr(
        "aria-current",
        "page"
      ),
      Scene.expect(Scene.role("button", { name: "Dashboard" })).toHaveHandler(
        "click"
      ),
      Scene.expect(Scene.role("link", { name: "Settings" })).toHaveAttr(
        "href",
        "/settings"
      )
    );
  });
});
